// missing-tool detector sketch for: Universal Design Recombination Engine
const registry = ['gen-data', 'sim-fluid', 'sim-rf'];
const task = { name: 'Universal_Design_Recombination_Engin', needs: ['sim-rf', 'sim-thermal', 'tool-opt'] };
const missing = task.needs.filter(n => registry.indexOf(n) < 0);
console.log(JSON.stringify({ task: task.name, registrySize: registry.length,
  missing: missing, proposed: missing.map(m => ({ tool: m, status: 'specified' })) }));

